+
+    .lead {
+      margin: 0;
+      max-width: 60ch;
+      color: var(--muted);
+      font-size: 1.03rem;
+    }
+
+    .faq {
+      display: grid;
+      gap: 1rem;
+    }
+
+    .example {
+      border: 1px solid var(--panel-border);
+      border-radius: var(--radius);
