+</head>
+<body>
+  <a class="skip-link" href="#main">Skip to main content</a>
+
+  <main id="main">
+    <section class="hero" aria-labelledby="page-title">
+      <h1 id="page-title">Cat FAQ</h1>
+      <p class="lead">A cozy collection of common cat questions, with each answer tucked away until you want it.</p>
+    </section>
+
+    <section class="faq" aria-label="Frequently asked questions about cats">
+      <div class="example">
+        <h2 class="question">
+          <button type="button" class="toggle" aria-expanded="false" aria-controls="answer-1" id="question-1">
+            <span>Why do cats purr?</span>
+            <span class="icon" aria-hidden="true">+</span>
