      color-scheme: dark;
      --bg: #0b1020;
      --bg-elevated: #121a2f;
      --panel: #16213a;
      --panel-border: #263458;
      --text: #f3f7ff;
      --muted: #b8c4e0;
      --accent: #8ab4ff;
      --accent-strong: #c1d8ff;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
      --radius: 20px;
