      font-size: clamp(2rem, 4vw, 3.25rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .lead {
      margin: 0;
      max-width: 60ch;
      color: var(--muted);
      font-size: 1.03rem;
    }

    .faq {
      display: grid;
      gap: 1rem;
    }

    .example {
      border: 1px solid var(--panel-border);
      border-radius: var(--radius);
      background: rgba(18, 26, 47, 0.92);
      overflow: clip;
      box-shadow: 0 12px 32px rgba(0, 0, 0, 0.24);
    }

    .question {
      margin: 0;
    }

